										struct pcap_pkthdr * pkh,
										struct AP_info ** ap_cur)
{
	REQUIRE(me != NULL);
	REQUIRE(bssid != NULL);
	REQUIRE(dest != NULL);
	REQUIRE(buffer != NULL);
	REQUIRE(h80211 != NULL);
	REQUIRE(ivs2 != NULL);
	REQUIRE(pkh != NULL);
	REQUIRE(ap_cur != NULL);

	*ap_cur = NULL;

	nb_pkt++;

	if (fmt == FORMAT_CAP)
	{
