static long load_hccapx_file(int fd)
{
	REQUIRE(fd >= 0);

	hccapx_t hx;
	struct AP_info * ap_cur = NULL;

	lseek(fd, 0, SEEK_SET);

	while (read(fd, &hx, sizeof(hccapx_t)) > 0)
	{
