static int do_wpa_crack(void)
{
	int cid;
	char key1[128];

	// display program banner
	if (!opt.is_quiet && !_speed_test)
	{
		if (opt.l33t) textcolor(TEXT_RESET, TEXT_WHITE, TEXT_BLACK);

