			return (1);
		}
		// update last recv time.
		st_cur->wpa.timestamp_last_us = now_us;

		if (st_cur->wpa.state == 0)
		{
			// no M1; so we store the M2 replay counter.
			st_cur->wpa.replay = replay_counter;
		}
		else if (st_cur->wpa.replay != replay_counter)
