			const size_t pmkid_offset = 2 + sizeof(rsn_oui) + 1;

			if (data[2 + sizeof(rsn_oui)] == 4
				&& ie_len >= pmkid_offset + 16
				&& memcmp(ZERO, data + pmkid_offset, 16) != 0)
